func (q *Queries) ListAIReservations(ctx context.Context, arg ListAIReservationsParams) ([]ListAIReservationsRow, error) {
	rows, err := q.db.Query(ctx, listAIReservations, arg.OrganizationID, arg.InstanceID, arg.EntitlementID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListAIReservationsRow
	for rows.Next() {
		var i ListAIReservationsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.InstanceID,
			&i.EntitlementID,
			&i.TransactionID,
			&i.Status,
			&i.ReportedAt,
			&i.CommittedAt,
			&i.ExpiresAt,
			&i.ModelRef,
			&i.ModelID,
			&i.RequestType,
			&i.RequestStatus,
			&i.InputTokens,
			&i.CacheReadInputTokens,
			&i.CacheWriteInputTokens,
			&i.OutputTokens,
			&i.Units,
			&i.UnitType,
			&i.DurationMs,
			&i.CreditConversionRuleID,
			&i.Authorized,
			&i.DenialReason,
			&i.CreditsReserved,
			&i.CreditsComputed,
			&i.CreditsCharged,
			&i.ValueBefore,
			&i.ValueAfter,
			&i.WindowStart,
			&i.RequestHash,
			&i.CommitHash,
			&i.ReserveResponse,
			&i.CommitResponse,
			&i.ModelSlug,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const resolveAIReadPair = `-- name: ResolveAIReadPair :one
SELECT i.id AS instance_id,e.id AS entitlement_id FROM instance i
JOIN entitlement e ON e.organization_id=i.organization_id AND e.slug=$1
JOIN license_entitlement le ON le.organization_id=i.organization_id AND le.license_id=i.license_id AND le.entitlement_id=e.id
WHERE i.organization_id=$2 AND i.slug=$3 AND e.type='NUMBER_AI_CREDIT'
`

type ResolveAIReadPairParams struct {
	EntitlementSlug string    `json:"entitlement_slug"`
	OrganizationID  uuid.UUID `json:"organization_id"`
	InstanceSlug    string    `json:"instance_slug"`
}

type ResolveAIReadPairRow struct {
	InstanceID    uuid.UUID `json:"instance_id"`
	EntitlementID uuid.UUID `json:"entitlement_id"`
}

func (q *Queries) ResolveAIReadPair(ctx context.Context, arg ResolveAIReadPairParams) (ResolveAIReadPairRow, error) {
	row := q.db.QueryRow(ctx, resolveAIReadPair, arg.EntitlementSlug, arg.OrganizationID, arg.InstanceSlug)
	var i ResolveAIReadPairRow
	err := row.Scan(&i.InstanceID, &i.EntitlementID)
	return i, err
}

const storeAIPhaseResponse = `-- name: StoreAIPhaseResponse :execrows
UPDATE ai_inference SET
reserve_response = CASE WHEN $1::text = 'reserve' THEN $2::jsonb ELSE reserve_response END,
commit_response = CASE WHEN $1::text = 'commit' THEN $2::jsonb ELSE commit_response END
WHERE id = $3 AND organization_id = $4
AND (($1::text='reserve' AND reserve_response IS NULL) OR ($1::text='commit' AND commit_response IS NULL))
`

type StoreAIPhaseResponseParams struct {
	Phase          string    `json:"phase"`
	Response       []byte    `json:"response"`
	ID             uuid.UUID `json:"id"`
	OrganizationID uuid.UUID `json:"organization_id"`
}

func (q *Queries) StoreAIPhaseResponse(ctx context.Context, arg StoreAIPhaseResponseParams) (int64, error) {
	result, err := q.db.Exec(ctx, storeAIPhaseResponse,
		arg.Phase,
		arg.Response,
		arg.ID,
		arg.OrganizationID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
